141	    /**
142	     * The known E.164 country calling codes this owner's telephone may carry, used only to split the
143	     * stored number into its country code and national digits for display. Australia ('+61') and the
144	     * North American Numbering Plan ('+1') mirror the codes the create endpoint recognises.
145	     */
146	    private static final String[] KNOWN_COUNTRY_CODES = {"61", "1"};
147	
148	    /**
149	     * The stored E.164 {@code telephone} formatted for human reading: the country calling code (kept
150	     * with its leading {@code '+'}), a space, then the national digits grouped in threes from the left
151	     * and separated by spaces (e.g. {@code +61412345678} becomes {@code "+61 412 345 678"}). The
152	     * country code is taken as the longest {@link #KNOWN_COUNTRY_CODES} match, defaulting to a
153	     * two-digit code when none is recognised. It is a derived value; the raw {@code telephone} stays in
154	     * E.164 form.
155	     *
156	     * @return the human-formatted telephone, or the raw {@code telephone} when it is {@code null} or
157	     *         not in E.164 form
158	     */
159	    public String getTelephoneDisplay() {
160	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
161	            return this.telephone;
162	        }
163	        String digits = this.telephone.substring(1);
164	        String countryCode = null;
165	        for (String code : KNOWN_COUNTRY_CODES) {
166	            if (digits.startsWith(code) && digits.length() > code.length()
167	                && (countryCode == null || code.length() > countryCode.length())) {
168	                countryCode = code;
169	            }
170	        }
171	        if (countryCode == null) {
172	            countryCode = digits.substring(0, Math.min(2, digits.length()));
173	        }
174	        String national = digits.substring(countryCode.length());
175	        StringBuilder sb = new StringBuilder("+").append(countryCode);
176	        for (int i = 0; i < national.length(); i += 3) {
177	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
178	        }
179	        return sb.toString();
180	    }
