293	    /**
294	     * The owner's membership points, a non-negative score. It starts at 0 and accumulates: 2 points
295	     * when an email address is present, 1 point when the owner has no namesakes ({@code namesakeCount}
296	     * is zero), 2 points for a household of 3 or more members ({@code householdMemberCount} is at least
297	     * 3), and 3 points for tenure &mdash; the number of whole days from {@code registrationDate} to
298	     * today &mdash; of more than 365 days.
299	     *
300	     * @return the derived membership points (0 or more)
301	     */
302	    public Integer getMembershipPoints() {
303	        int points = 0;
304	        if (this.email != null && !this.email.isBlank()) {
305	            points += 2;
306	        }
307	        if (this.namesakeCount != null && this.namesakeCount == 0) {
308	            points += 1;
309	        }
310	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
311	            points += 2;
312	        }
313	        if (this.registrationDate != null
314	            && java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
315	            points += 3;
316	        }
317	        return points;
318	    }
319	
320	    /**
321	     * The owner's membership level, a number from 1 to 4, derived from {@link #getMembershipPoints()}:
322	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more
323	     * points.
324	     *
325	     * @return the derived membership level (1 to 4)
326	     */
327	    public Integer getMembershipLevel() {
328	        int points = getMembershipPoints();
329	        if (points >= 6) {
330	            return 4;
331	        }
332	        if (points >= 4) {
333	            return 3;
334	        }
335	        if (points >= 2) {
336	            return 2;
337	        }
338	        return 1;
339	    }
340	
341	    /**
342	     * The Luhn check digit (0-9) computed over the digits contained in this owner's
343	     * {@code customerCode}. Non-digit characters are ignored; the rightmost digit is doubled.
344	     *
345	     * @return the single Luhn check digit, or {@code null} when there is no customer code
346	     */
347	    public Integer getCheckDigit() {
348	        if (this.customerCode == null) {
349	            return null;
350	        }
351	        int sum = 0;
352	        boolean dbl = true;
353	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
354	            char c = this.customerCode.charAt(i);
355	            if (c < '0' || c > '9') {
356	                continue;
357	            }
358	            int d = c - '0';
359	            if (dbl) {
360	                d *= 2;
361	                if (d > 9) {
362	                    d -= 9;
363	                }
364	            }
365	            sum += d;
366	            dbl = !dbl;
367	        }
368	        return (10 - (sum % 10)) % 10;
369	    }
370	
371	    /**
372	     * The owner's age band, derived from {@code birthDate} computed against {@code registrationDate}:
373	     * {@code MINOR} when the owner is under 18, {@code ADULT} from 18 to 64, and {@code SENIOR} at 65
374	     * or older. It is a derived, non-persistent value; when no {@code birthDate} is present it is
375	     * {@code null}.
376	     *
377	     * @return {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"}, or {@code null} when no birth date
378	     *         is present
379	     */
380	    public String getAgeBand() {
381	        if (this.birthDate == null) {
382	            return null;
383	        }
384	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
385	        int age = java.time.Period.between(this.birthDate, reference).getYears();
386	        if (age < 18) {
387	            return "MINOR";
388	        }
389	        if (age < 65) {
390	            return "ADULT";
391	        }
392	        return "SENIOR";
393	    }
394	
395	    /**
396	     * The owner's preferred contact channel, derived from the stored fields: {@code EMAIL} when an
397	     * email address is present, otherwise {@code PHONE}.
398	     *
399	     * @return {@code "EMAIL"} when an email address is present, otherwise {@code "PHONE"}
400	     */
401	    public String getContactPreference() {
402	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
403	    }
404	
405	    /**
406	     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
407	     * owner's normalized telephone, its email (empty when none) and its {@code householdId} (empty
408	     * when none) joined by {@code '|'}. Because the telephone is part of the key, two members of the
409	     * same household with different telephones have different identity keys; only owners whose whole
410	     * key is identical are duplicates.
411	     *
412	     * @return the {@code normalizedTelephone|email|householdId} identity key
413	     */
414	    public String getIdentityKey() {
415	        String telephonePart = this.telephone == null ? "" : this.telephone;
416	        String emailPart = this.email == null ? "" : this.email;
417	        String householdPart = this.householdId == null ? "" : this.householdId;
418	        return telephonePart + '|' + emailPart + '|' + householdPart;
419	    }
420	
421	    protected Set<Pet> getPetsInternal() {
422	        if (this.pets == null) {
423	            this.pets = new HashSet<>();
424	        }
425	        return this.pets;
426	    }
427	
428	    protected void setPetsInternal(Set<Pet> pets) {
429	        this.pets = pets;
430	    }
431	
432	    public List<Pet> getPets() {
433	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
434	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
435	        return Collections.unmodifiableList(sortedPets);
436	    }
437	
438	    public void setPets(List<Pet> pets) {
439	        this.pets = new HashSet<>(pets);
440	    }
441	
442	    public void addPet(Pet pet) {
443	        getPetsInternal().add(pet);
444	        pet.setOwner(this);
445	    }
446	
447	    /**
448	     * Return the Pet with the given name, or null if none found for this Owner.
449	     *
450	     * @param name to test
451	     * @return true if pet name is already in use
452	     */
453	    public Pet getPet(String name) {
454	        return getPet(name, false);
455	    }
456	
457	    /**
458	     * Return the Pet with the given name, or null if none found for this Owner.
459	     *
460	     * @param name to test
461	     * @return true if pet name is already in use
462	     */
463	    public Pet getPet(String name, boolean ignoreNew) {
464	        name = name.toLowerCase();
465	        for (Pet pet : getPetsInternal()) {
466	            if (!ignoreNew || !pet.isNew()) {
467	                String compName = pet.getName();
468	                compName = compName.toLowerCase();
469	                if (compName.equals(name)) {
470	                    return pet;
471	                }
472	            }
473	        }
474	        return null;
475	    }
476	
477	    public Pet getPet(Integer petId) {
478	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
479	    }
480	
481	    @Override
482	    public String toString() {
483	        return new ToStringCreator(this)
484	
485	            .append("id", this.getId())
486	            .append("new", this.isNew())
487	            .append("lastName", this.getLastName())
488	            .append("firstName", this.getFirstName())
489	            .append("address", this.address)
490	            .append("city", this.city)
491	            .append("telephone", this.telephone)
492	            .toString();
493	    }
494	}
