252	    @Transactional(readOnly = true)
253	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
254	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
255	    }
256	
257	    private <T> T findEntityById(Supplier<T> supplier) {
258	        try {
259	            return supplier.get();
260	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
261	            // Just ignore not found exceptions for Jdbc/Jpa realization
262	            return null;
263	        }
264	    }
265	
266	}
