66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Syntactic check for an email address: a non-empty local part, an '@', a domain with at least
74	     * one dot and a two-or-more letter top-level label. Case-insensitive; the accepted value is
75	     * stored lower-cased.
76	     */
77	    private static final Pattern EMAIL_PATTERN =
78	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
79	
80	    /** A well-formed postcode: exactly four digits. */
81	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
82	
83	    /**
84	     * Email domains belonging to disposable-address providers. An owner whose email domain (the part
85	     * after the '@', compared case-insensitively) is one of these is rejected: such addresses are
86	     * throwaway and unsuitable for a durable owner record.
87	     */
88	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
89	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
90	
91	    /**
92	     * Region -&gt; inclusive 4-digit postcode range {@code {low, high}}. A postcode supplied for an
93	     * owner whose city maps to one of these regions (see {@link LocalityLookup}) must fall within the
94	     * region's range; a city with no known region ({@code "UNKNOWN"}) accepts any 4-digit postcode.
95	     */
96	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
97	        "NSW", new int[] {2000, 2099},
98	        "VIC", new int[] {3000, 3099},
99	        "QLD", new int[] {4000, 4099});
100	
101	    /** Dedicated audit logger; one line is emitted per successful owner create. */
102	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
103	
104	    /**
105	     * The maximum number of owners a single city may contain. Once a city already holds this many
106	     * owners, any further create naming that city is rejected as a conflict.
107	     */
108	    private static final int MAX_OWNERS_PER_CITY = 50;
109	
110	    /**
111	     * The maximum number of owners that may be registered in a single day. Once this many owners
112	     * already carry today's registration date, any further create is rejected as too many requests.
113	     */
114	    private static final int MAX_OWNERS_PER_DAY = 100;
115	
116	    /**
117	     * The number of owners that must already be registered on today's business day before a response
118	     * carries a bulk-signup warning. Once more than this many owners already carry today's
119	     * registration date, responses set {@code bulkSignupWarning} true.
120	     */
121	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
122	
123	    private final ClinicService clinicService;
124	
125	    private final OwnerMapper ownerMapper;
126	
127	    private final PetMapper petMapper;
128	
129	    private final VisitMapper visitMapper;
130	
131	    public OwnerRestControllerV1(ClinicService clinicService,
132	                                 OwnerMapper ownerMapper,
133	                                 PetMapper petMapper,
134	                                 VisitMapper visitMapper) {
135	        this.clinicService = clinicService;
136	        this.ownerMapper = ownerMapper;
137	        this.petMapper = petMapper;
138	        this.visitMapper = visitMapper;
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
144	        Collection<Owner> owners;
145	        if (lastName != null) {
146	            owners = this.clinicService.findOwnerByLastName(lastName);
147	        } else {
148	            owners = this.clinicService.findAllOwners();
149	        }
150	        if (owners.isEmpty()) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        owners.forEach(owner -> owner.setHouseholdMemberCount(countHouseholdMembers(owner)));
154	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
160	        Owner owner = this.clinicService.findOwnerById(ownerId);
161	        if (owner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        OwnerDto ownerDto = toOwnerDto(owner);
165	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
166	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Override
171	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
172	        validateRequiredOwnerFields(ownerFieldsDto);
173	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
174	        LocalDate suppliedOrDefaultDate =
175	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
176	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
177	        rejectDailyLimitExceeded(registrationDate);
178	        rejectCityAtCapacity(ownerFieldsDto.getCity());
179	        HttpHeaders headers = new HttpHeaders();
180	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
181	        validatePostcode(owner.getCity(), owner.getPostcode());
182	        applyAddress(owner);
183	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
184	        owner.setTelephone(normalizedTelephone);
185	        boolean declaredHouseholdMember = applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
186	        owner.setEmail(normalizeEmail(owner.getEmail()));
187	        rejectDuplicateIdentity(owner);
188	        applyPossibleDuplicate(owner, declaredHouseholdMember);
189	        owner.setRegistrationDate(registrationDate);
190	        owner.setCustomerCode(
191	            generateCustomerCode(owner.getPostcode(), owner.getCity(), normalizedTelephone, owner.getLastName()));
192	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
193	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
194	        this.clinicService.saveOwner(owner);
195	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
196	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
197	            owner.getMembershipNumber());
198	        OwnerDto ownerDto = toOwnerDto(owner);
199	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
200	        headers.setLocation(UriComponentsBuilder.newInstance()
201	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
202	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
203	    }
204	
205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Override
207	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
208	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
209	        if (currentOwner == null) {
210	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
211	        }
212	        currentOwner.setAddress(ownerFieldsDto.getAddress());
213	        currentOwner.setCity(ownerFieldsDto.getCity());
214	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
215	        currentOwner.setLastName(ownerFieldsDto.getLastName());
216	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
217	        this.clinicService.saveOwner(currentOwner);
218	        return new ResponseEntity<>(toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Transactional
223	    @Override
224	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
225	        Owner owner = this.clinicService.findOwnerById(ownerId);
226	        if (owner == null) {
227	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
228	        }
229	        this.clinicService.deleteOwner(owner);
230	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
231	    }
232	
233	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
234	    @Override
235	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
236	        Owner owner = this.clinicService.findOwnerById(ownerId);
237	        if (owner == null) {
238	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
239	        }
240	        HttpHeaders headers = new HttpHeaders();
241	        Pet pet = petMapper.toPet(petFieldsDto);
242	        owner.setId(ownerId);
243	        pet.setOwner(owner);
244	        pet.getType().setName(null);
245	        this.clinicService.savePet(pet);
246	        PetDto petDto = petMapper.toPetDto(pet);
247	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
248	            .buildAndExpand(pet.getId()).toUri());
249	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
250	    }
251	
252	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
253	    @Override
254	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
255	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
256	        if (currentOwner != null) {
257	            Pet currentPet = this.clinicService.findPetById(petId);
258	            if (currentPet != null) {
259	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
260	                currentPet.setName(petFieldsDto.getName());
261	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
262	                this.clinicService.savePet(currentPet);
263	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
264	            }
265	        }
266	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
267	    }
268	
269	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
270	    @Override
271	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
272	        HttpHeaders headers = new HttpHeaders();
273	        Visit visit = visitMapper.toVisit(visitFieldsDto);
274	        Pet pet = new Pet();
275	        pet.setId(petId);
276	        visit.setPet(pet);
277	        this.clinicService.saveVisit(visit);
278	        VisitDto visitDto = visitMapper.toVisitDto(visit);
279	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
280	            .buildAndExpand(visit.getId()).toUri());
281	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
282	    }
283	
284	
285	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
286	    @Override
287	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
288	        Owner owner = this.clinicService.findOwnerById(ownerId);
289	        if (owner != null) {
290	            Pet pet = owner.getPet(petId);
291	            if (pet != null) {
292	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
293	            }
294	        }
295	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
296	    }
297	
298	    /**
299	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
300	     * offending field is collected so the caller learns exactly which values must be supplied.
301	     *
302	     * @param ownerFieldsDto the submitted owner payload
303	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
304	     *         telephone is missing or blank
305	     */
306	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
307	        List<String> missingFields = new ArrayList<>();
308	        if (isBlank(ownerFieldsDto.getFirstName())) {
309	            missingFields.add("firstName");
310	        }
311	        if (isBlank(ownerFieldsDto.getLastName())) {
312	            missingFields.add("lastName");
313	        }
314	        if (isBlank(ownerFieldsDto.getAddressLine1())
315	            && isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
316	            missingFields.add("address");
317	        }
318	        if (isBlank(ownerFieldsDto.getCity())) {
319	            missingFields.add("city");
320	        }
321	        if (isBlank(ownerFieldsDto.getTelephone())) {
322	            missingFields.add("telephone");
323	        }
324	        if (!missingFields.isEmpty()) {
325	            throw new MissingOwnerFieldsException(missingFields);
326	        }
327	    }
328	
329	    private boolean isBlank(String value) {
330	        return value == null || value.isBlank();
331	    }
332	
333	    /**
334	     * Rejects an owner create whose supplied {@code registrationDate} is later than the server's
335	     * current date. A registration date may not lie in the future; a value equal to today or in the
336	     * past is accepted, and an absent date is left to default to the server date.
337	     *
338	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
339	     * @throws InvalidOwnerFieldsException if the supplied date is after the server's current date
340	     */
341	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
342	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
343	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
344	        }
345	    }
346	
347	    /**
348	     * Counts the existing owners who, before this create, already share the given first and last name.
349	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
350	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
351	     * case or spacing still count as the same name.
352	     *
353	     * @param firstName the first name of the owner being created
354	     * @param lastName the last name of the owner being created
355	     * @return the number of existing owners sharing both names (zero when none)
356	     */
357	    private int countNamesakes(String firstName, String lastName) {
358	        String first = normalizeHouseholdField(firstName);
359	        String last = normalizeHouseholdField(lastName);
360	        return (int) this.clinicService.findAllOwners().stream()
361	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
362	                && normalizeHouseholdField(existing.getLastName()).equals(last))
363	            .count();
364	    }
365	
366	    /**
367	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
368	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
369	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
370	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
371	     * more owners the create is rejected as a conflict.
372	     *
373	     * @param city the city of the owner being created
374	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
375	     */
376	    /**
377	     * Rejects an owner create once the maximum number of owners have already been registered on the
378	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
379	     * which is always a business day (a weekend effective date is rolled forward to the following
380	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
381	     * business day the create is rejected as too many requests. Because a weekend effective date is
382	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
383	     *
384	     * @param businessDay the adjusted business day the owner being created would be registered on
385	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
386	     */
387	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
388	        long ownersOnDay = this.clinicService.findAllOwners().stream()
389	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
390	            .count();
391	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
392	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
393	        }
394	    }
395	
396	    /**
397	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
398	     * forward to the following Monday; a weekday is returned unchanged. This applies whether the date
399	     * was supplied on the request or defaulted to the server's current date.
400	     *
401	     * @param date the effective registration date (supplied or defaulted)
402	     * @return the same date when it is a weekday, otherwise the following Monday
403	     */
404	    /**
405	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
406	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
407	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
408	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
409	     *
410	     * @return {@code true} when more than the threshold number of owners are already registered on
411	     *         today's business day, otherwise {@code false}
412	     */
413	    private boolean isBulkSignupWarningActive() {
414	        LocalDate today = toBusinessDay(LocalDate.now());
415	        long ownersToday = this.clinicService.findAllOwners().stream()
416	            .filter(existing -> today.equals(existing.getRegistrationDate()))
417	            .count();
418	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
419	    }
420	
421	    private LocalDate toBusinessDay(LocalDate date) {
422	        return switch (date.getDayOfWeek()) {
423	            case SATURDAY -> date.plusDays(2);
424	            case SUNDAY -> date.plusDays(1);
425	            default -> date;
426	        };
427	    }
428	
429	    private void rejectCityAtCapacity(String city) {
430	        String normalizedCity = normalizeHouseholdField(city);
431	        long ownersInCity = this.clinicService.findAllOwners().stream()
432	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
433	            .count();
434	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
435	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
436	        }
437	    }
438	
439	    /**
440	     * Builds an owner's customer code, formatted '&lt;REGION&gt;-&lt;HASH8&gt;'. REGION is the region
441	     * code derived from the owner's postcode (falling back to their city; see {@link LocalityLookup}),
442	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the owner's
443	     * normalized telephone concatenated with their last name (e.g. 'NSW-1A2B3C4D'). Two owners resolve
444	     * to the same base code only when they share a region and produce the same telephone-and-last-name
445	     * hash; when the computed code collides with an existing owner's customer code it is de-duplicated
446	     * by appending '-&lt;n&gt;' with the smallest {@code n} of 2 or more that makes it unique.
447	     *
448	     * @param postcode the owner's postcode, used first to derive the region
449	     * @param city the owner's city, used to derive the region when the postcode maps to none
450	     * @param normalizedTelephone the owner's normalized (E.164) telephone
451	     * @param lastName the owner's last name
452	     * @return the formatted, de-duplicated customer code
453	     */
454	    private String generateCustomerCode(String postcode, String city, String normalizedTelephone, String lastName) {
455	        String region = LocalityLookup.forPostcodeAndCity(postcode, city);
456	        String hash8 = sha256UpperHex(normalizedTelephone + lastName, 8);
457	        String baseCode = region + "-" + hash8;
458	        return deduplicateCustomerCode(baseCode);
459	    }
460	
461	    /**
462	     * De-duplicates a computed customer code against every existing owner's customer code. When no
463	     * existing owner already carries the base code it is returned unchanged; otherwise '-&lt;n&gt;' is
464	     * appended with the smallest {@code n} of 2 or more that yields a code no existing owner holds.
465	     *
466	     * @param baseCode the computed, formatted customer code before de-duplication
467	     * @return the base code when unique, otherwise the base code suffixed with '-&lt;n&gt;'
468	     */
469	    private String deduplicateCustomerCode(String baseCode) {
470	        java.util.Set<String> existingCodes = this.clinicService.findAllOwners().stream()
471	            .map(Owner::getCustomerCode)
472	            .filter(java.util.Objects::nonNull)
473	            .collect(java.util.stream.Collectors.toSet());
474	        if (!existingCodes.contains(baseCode)) {
475	            return baseCode;
476	        }
477	        int n = 2;
478	        while (existingCodes.contains(baseCode + "-" + n)) {
479	            n++;
480	        }
481	        return baseCode + "-" + n;
482	    }
483	
484	    /**
485	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
486	     * customerCode is the owner's customer code and YY is the last two digits of the
487	     * registrationDate year (e.g. 'NSW-1A2B3C4D-M26').
488	     *
489	     * @param customerCode the owner's customer code
490	     * @param registrationDate the owner's registration date
491	     * @return the formatted membership number
492	     */
493	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
494	        String yy = String.format("%02d", registrationDate.getYear() % 100);
495	        return customerCode + "-M" + yy;
496	    }
497	
498	    /**
499	     * The exact number of national (subscriber) digits an E.164 telephone must carry for a given
500	     * country calling code. Australia ('+61') uses 9 national digits and the North American
501	     * Numbering Plan ('+1') uses 10. Country codes not listed here are only bound by the generic
502	     * E.164 length (8 to 15 digits overall).
503	     */
504	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
505	        java.util.Map.of("61", 9, "1", 10);
506	
507	    /**
508	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
509	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
510	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
511	     * digits. The result must be a '+' followed by 8 to 15 digits, and its national number must have
512	     * the exact length its country code requires ('+61' needs 9 national digits, '+1' needs 10). This
513	     * E.164 string is what gets stored and returned.
514	     *
515	     * @param telephone the raw telephone value from the request
516	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
517	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number or its
518	     *         national number has the wrong length for its country code
519	     */
520	    private String normalizeTelephone(String telephone) {
521	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
522	        String e164;
523	        if (cleaned.startsWith("+")) {
524	            e164 = cleaned;
525	        } else {
526	            String national = cleaned;
527	            if (national.startsWith("0")) {
528	                national = national.substring(1);
529	            }
530	            e164 = "+61" + national;
531	        }
532	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
533	            throw new InvalidOwnerFieldsException(List.of("telephone"));
534	        }
535	        validateNationalNumberLength(e164);
536	        return e164;
537	    }
538	
539	    /**
540	     * Rejects an E.164 telephone whose national number does not have the exact length its country
541	     * calling code requires. The digits after the leading '+' are split into the longest matching
542	     * country code from {@link #NATIONAL_NUMBER_LENGTHS} and the remaining national number; when the
543	     * code is known and the national number's length differs from the required count the telephone is
544	     * rejected. Numbers whose country code is not listed are left to the generic E.164 length rule.
545	     *
546	     * @param e164 the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
547	     * @throws InvalidOwnerFieldsException if the national number has the wrong length for its country code
548	     */
549	    private void validateNationalNumberLength(String e164) {
550	        String digits = e164.substring(1);
551	        for (int codeLength = Math.min(3, digits.length()); codeLength >= 1; codeLength--) {
552	            String countryCode = digits.substring(0, codeLength);
553	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
554	            if (requiredNationalLength != null) {
555	                int nationalLength = digits.length() - codeLength;
556	                if (nationalLength != requiredNationalLength) {
557	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
558	                }
559	                return;
560	            }
561	        }
562	    }
563	
564	    /**
565	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
566	     * left unset. When a value is present it must be a syntactically valid address whose domain is not
567	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); the normalized form
568	     * stored and returned is the value lower-cased.
569	     *
570	     * @param email the raw email value from the request, or {@code null} when none was supplied
571	     * @return the lower-cased email, or {@code null} when no email was supplied
572	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address or
573	     *         its domain is on the disposable-domain blocklist
574	     */
575	    private String normalizeEmail(String email) {
576	        if (email == null || email.isBlank()) {
577	            return null;
578	        }
579	        if (!EMAIL_PATTERN.matcher(email).matches()) {
580	            throw new InvalidOwnerFieldsException(List.of("email"));
581	        }
582	        String normalized = email.toLowerCase(Locale.ROOT);
583	        String domain = normalized.substring(normalized.indexOf('@') + 1);
584	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
585	            throw new InvalidOwnerFieldsException(List.of("email"));
586	        }
587	        return normalized;
588	    }
589	
590	    /**
591	     * Validates an optional postcode supplied on create. A postcode is validated only when present:
592	     * an absent (null or blank) postcode is accepted, keeping the create request backward-compatible.
593	     * When present it must be exactly four digits and, when the owner's city maps to a known region
594	     * (see {@link LocalityLookup}), must fall within that region's inclusive range
595	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
596	     * region accepts any four-digit postcode.
597	     *
598	     * @param city the owner's city, used to derive the region whose range the postcode must satisfy
599	     * @param postcode the raw postcode value from the request, or {@code null} when none was supplied
600	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
601	     *         for the city's region
602	     */
603	    private void validatePostcode(String city, String postcode) {
604	        if (postcode == null || postcode.isBlank()) {
605	            return;
606	        }
607	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
608	            throw new InvalidOwnerFieldsException(List.of("postcode"));
609	        }
610	        int[] range = REGION_POSTCODE_RANGES.get(LocalityLookup.forCity(city));
611	        if (range == null) {
612	            return;
613	        }
614	        int value = Integer.parseInt(postcode);
615	        if (value < range[0] || value > range[1]) {
616	            throw new InvalidOwnerFieldsException(List.of("postcode"));
617	        }
618	    }
619	
620	    /**
621	     * Resolves an owner's address from the supplied structured and flat fields, preferring the
622	     * structured form. Whichever address fields were supplied are normalized (see
623	     * {@link #normalizeAddress(String)}). When a non-blank {@code addressLine1} is supplied the
624	     * structured form wins: {@code addressLine1} and {@code addressLine2} are stored normalized (an
625	     * absent or blank {@code addressLine2} is cleared) and the composed {@code address} is the
626	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
627	     * appended when the latter is present. When no {@code addressLine1} is supplied the flat
628	     * {@code address} is used unchanged for backward compatibility and the structured lines are
629	     * cleared. The composed {@code address} is what every later step reads.
630	     *
631	     * @param owner the owner being created, mapped from the request but not yet normalized
632	     */
633	    private void applyAddress(Owner owner) {
634	        String line1 = normalizeAddress(owner.getAddressLine1());
635	        String line2 = normalizeAddress(owner.getAddressLine2());
636	        String flat = normalizeAddress(owner.getAddress());
637	        if (!line1.isEmpty()) {
638	            owner.setAddressLine1(line1);
639	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
640	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
641	        } else {
642	            owner.setAddressLine1(null);
643	            owner.setAddressLine2(null);
644	            owner.setAddress(flat);
645	        }
646	    }
647	
648	    /**
649	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
650	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
651	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
652	     * normalized form is what gets stored, returned and used for every address comparison (the
653	     * required-field check, household duplicate detection and the shared household id).
654	     *
655	     * @param address the raw address value from the request, or {@code null}
656	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
657	     */
658	    private String normalizeAddress(String address) {
659	        if (address == null) {
660	            return "";
661	        }
662	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
663	        if (collapsed.isEmpty()) {
664	            return "";
665	        }
666	        String[] tokens = collapsed.split(" ");
667	        for (int i = 0; i < tokens.length; i++) {
668	            switch (tokens[i]) {
669	                case "ST" -> tokens[i] = "STREET";
670	                case "RD" -> tokens[i] = "ROAD";
671	                case "AVE" -> tokens[i] = "AVENUE";
672	                default -> { }
673	            }
674	        }
675	        return String.join(" ", tokens);
676	    }
677	
678	    /**
679	     * Rejects an owner create whose {@code identityKey} exactly matches an existing owner's. The
680	     * identity key - the owner's normalized telephone, email (empty when none) and {@code householdId}
681	     * (empty when none) joined by {@code '|'} - is the single derived value that subsumes the former
682	     * separate telephone, email and household duplicate checks. Only a whole-key match is a conflict,
683	     * so two members of one household with different telephones have different keys and are both
684	     * allowed; only an owner whose entire key is identical is a duplicate.
685	     *
686	     * @param owner the owner being created, with its telephone, email and householdId already resolved
687	     * @throws DuplicateOwnerIdentityException if another owner already has this exact identity key
688	     */
689	    private void rejectDuplicateIdentity(Owner owner) {
690	        String identityKey = owner.getIdentityKey();
691	        boolean inUse = this.clinicService.findAllOwners().stream()
692	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
693	        if (inUse) {
694	            throw new DuplicateOwnerIdentityException(identityKey);
695	        }
696	    }
697	
698	    /**
699	     * Flags an owner being created as a possible (soft) duplicate. A soft match is an existing owner
700	     * that shares this owner's last name (compared case-insensitively with collapsed whitespace) and
701	     * postcode but carries a different (normalized) telephone; such an owner is not a hard duplicate
702	     * (its identity key differs) and is still created. When at least one soft match exists,
703	     * {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to the lowest-id match;
704	     * otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left unset.
705	     * <p>
706	     * A declared household member - an owner that acknowledged sharing an existing household via
707	     * {@code sharesHousehold} - is never flagged: having deliberately joined the household it is not a
708	     * suspected duplicate, so {@code possibleDuplicate} is set false without inspecting other owners.
709	     *
710	     * @param owner the owner being created, with its last name, postcode and normalized telephone resolved
711	     * @param declaredHouseholdMember whether the owner joined an existing household by acknowledging it
712	     */
713	    private void applyPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
714	        if (declaredHouseholdMember) {
715	            owner.setPossibleDuplicate(false);
716	            return;
717	        }
718	        String lastName = normalizeHouseholdField(owner.getLastName());
719	        String postcode = owner.getPostcode();
720	        String telephone = owner.getTelephone();
721	        Owner match = null;
722	        if (postcode != null && !postcode.isBlank()) {
723	            match = this.clinicService.findAllOwners().stream()
724	                .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName))
725	                .filter(existing -> postcode.equals(existing.getPostcode()))
726	                .filter(existing -> !java.util.Objects.equals(telephone, existing.getTelephone()))
727	                .min(java.util.Comparator.comparing(Owner::getId))
728	                .orElse(null);
729	        }
730	        if (match != null) {
731	            owner.setPossibleDuplicate(true);
732	            owner.setPossibleDuplicateOf(match.getId());
733	        } else {
734	            owner.setPossibleDuplicate(false);
735	        }
736	    }
737	
738	    /**
739	     * Maps an owner to its DTO, first populating the owner's {@link Owner#getHouseholdMemberCount()
740	     * household member count} for the response.
741	     *
742	     * @param owner the owner to map
743	     * @return the mapped owner DTO
744	     */
745	    private OwnerDto toOwnerDto(Owner owner) {
746	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
747	        return ownerMapper.toOwnerDto(owner);
748	    }
749	
750	    /**
751	     * Counts the members of the given owner's household - the owners that share this owner's
752	     * {@code householdId}, including the owner itself. An owner with no household ({@code householdId}
753	     * is {@code null}) is its own sole member, so the count is one.
754	     *
755	     * @param owner the owner whose household is being sized
756	     * @return the number of owners sharing this owner's household (one when it has no household)
757	     */
758	    private int countHouseholdMembers(Owner owner) {
759	        String householdId = owner.getHouseholdId();
760	        if (householdId == null) {
761	            return 1;
762	        }
763	        return (int) this.clinicService.findAllOwners().stream()
764	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
765	            .count();
766	    }
767	
768	    /**
769	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
770	     * last name and a postcode: the {@code householdId} is derived deterministically from the
771	     * normalized last name and the postcode (see {@link #generateHouseholdId(String, String)}), so two
772	     * owners with the same last name and postcode always resolve to the same identifier and belong to
773	     * the same household automatically - no acknowledgement is needed to create the link.
774	     * <p>
775	     * When the owner supplies a postcode its {@code householdId} is always assigned. If that household
776	     * already has at least one member, the create is a household duplicate: it is rejected with a 409
777	     * unless {@code sharesHousehold} is true, in which case the owner is created as a declared member
778	     * of that household. An owner with no postcode belongs to no household and is left without an
779	     * identifier.
780	     *
781	     * @param owner the owner being created
782	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
783	     * @return {@code true} when the owner joined an existing household as a declared member, otherwise
784	     *         {@code false}
785	     * @throws DuplicateOwnerHouseholdException when the household already exists and the create did not
786	     *         acknowledge it via {@code sharesHousehold}
787	     */
788	    private boolean applyHousehold(Owner owner, Boolean sharesHousehold) {
789	        String postcode = owner.getPostcode();
790	        if (postcode == null || postcode.isBlank()) {
791	            return false;
792	        }
793	        String lastName = normalizeHouseholdField(owner.getLastName());
794	        String householdId = generateHouseholdId(lastName, postcode);
795	        owner.setHouseholdId(householdId);
796	        boolean hasExistingMember = this.clinicService.findAllOwners().stream()
797	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
798	        if (!hasExistingMember) {
799	            return false;
800	        }
801	        if (!Boolean.TRUE.equals(sharesHousehold)) {
802	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), postcode);
803	        }
804	        return true;
805	    }
806	
807	    /**
808	     * Builds the stable identifier shared by the members of one household. It is derived purely from
809	     * the normalized last name and the postcode, so every owner sharing a last name and postcode
810	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
811	     * two fields joined by a single '|'.
812	     *
813	     * @param normalizedLastName the household's last name, already normalized for comparison
814	     * @param postcode the household's postcode
815	     * @return the shared household identifier
816	     */
817	    private String generateHouseholdId(String normalizedLastName, String postcode) {
818	        String key = normalizedLastName + '|' + postcode;
819	        try {
820	            byte[] digest = MessageDigest.getInstance("SHA-256")
821	                .digest(key.getBytes(StandardCharsets.UTF_8));
822	            StringBuilder hex = new StringBuilder();
823	            for (byte b : digest) {
824	                hex.append(String.format("%02X", b));
825	                if (hex.length() >= 12) {
826	                    break;
827	                }
828	            }
829	            return hex.substring(0, 12);
830	        } catch (NoSuchAlgorithmException e) {
831	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
832	        }
833	    }
834	
835	    /**
836	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the given
837	     * input's UTF-8 bytes. Used to derive the customer code's stable, deterministic hash component from
838	     * the owner's normalized telephone and last name.
839	     *
840	     * @param input the string to digest
841	     * @param length the number of leading upper-case hex characters to return
842	     * @return the first {@code length} upper-case hex characters of the SHA-256 digest
843	     */
844	    private String sha256UpperHex(String input, int length) {
845	        try {
846	            byte[] digest = MessageDigest.getInstance("SHA-256")
847	                .digest(input.getBytes(StandardCharsets.UTF_8));
848	            StringBuilder hex = new StringBuilder();
849	            for (byte b : digest) {
850	                hex.append(String.format("%02X", b));
851	                if (hex.length() >= length) {
852	                    break;
853	                }
854	            }
855	            return hex.substring(0, length);
856	        } catch (NoSuchAlgorithmException e) {
857	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
858	        }
859	    }
860	
861	    /**
862	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
863	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
864	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
865	     * expands common abbreviations.
866	     *
867	     * @param value the raw last name, or {@code null}
868	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
869	     */
870	    private String normalizeHouseholdField(String value) {
871	        if (value == null) {
872	            return "";
873	        }
874	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
875	    }
876	}
